{
    # Progressive 32-block REVOLT Classic in the calibration's native units.
    # Load the prepared profile's parameter ports before processing frames.
    # The host carries controller-constraint-feedback to constraint-feedback
    # after each successful complete frame, with zero feedback at reset.
    node.name = test-julia-rtc-classic-row-feedback
    filter.graph = {
        nodes = [
            {
                type = ndarray
                name = pixel-calibration
                label = pixel-calibration-row-u16-f32
                config = {
                    image_rows = 352
                    image_columns = 352
                    row_block_rows = 11
                    initial_flat = null
                    initial_background = null
                }
            }
            {
                type = ndarray
                name = shack-hartmann
                label = shack-hartmann-measurement-block-f32
                config = {
                    image_rows = 352
                    image_columns = 352
                    row_block_rows = 11
                    subaperture_rows = 22
                    subaperture_columns = 22
                    subaperture_count = 188
                    initial_subaperture_origins = null
                    coordinate_scale = 1.0
                    pixel_threshold = 20.0
                    flux_threshold = 1000.0
                    reference_slopes = null
                    active = null
                    measurements_schema = org.example.ao.measurement-block/1
                    column_indices_schema = org.example.ao.reconstructor-column-indices/1
                    measurement_count_schema = org.example.ao.measurement-block-count/1
                }
            }
            {
                type = ndarray
                name = reconstruction
                label = incremental-dense-reconstructor-f32
                config = {
                    measurement_count = 376
                    measurement_block_capacity = 376
                    blocks_per_sample = 32
                    reconstructed_count = 221
                    measurements_schema = org.example.ao.measurement-block/1
                    column_indices_schema = org.example.ao.reconstructor-column-indices/1
                    measurement_count_schema = org.example.ao.measurement-block-count/1
                    reconstructor_schema = org.calculon.ao.shwfs-reconstructor/1
                    initial_reconstructor = null
                    reconstructed_schema = org.calculon.ao.controller-residual-error/1
                }
            }
            {
                type = ndarray
                name = closed-loop-correction
                label = closed-loop-correction-f32
                config = { state_length = 221 hidden_mode_count = 1 }
                props = {
                    gain = -0.3
                    pole = 0.99
                    # CL-02: HEART's feedback order requires k_aw = pole.
                    anti-windup-gain = 0.99
                    hidden-mode-gain = 0.0
                }
            }
            {
                type = ndarray
                name = controller-to-vdm
                label = controller-to-vdm-f32
                config = { controller_command_extent = 221 vdm_size = 221 }
            }
            {
                type = ndarray
                name = vdm-to-pdm
                label = vdm-to-pdm-f32
                config = {
                    active_vdm_size = 221
                    full_vdm_size = 277
                    physical_actuator_extent = 277
                }
            }
            {
                type = ndarray
                name = pdm-command
                label = pdm-command-f32
                config = {
                    actuator_count = 277
                    lower_limit = -0.8
                    upper_limit = 0.8
                    slew_limit = null
                    slew_mode = independent
                    initial_current = null
                    quantization_origin = null
                    quantization_step = null
                    dither_seed = null
                }
            }
            {
                type = ndarray
                name = pdm-feedback-to-vdm
                label = pdm-feedback-to-vdm-f32
                config = {
                    active_vdm_size = 221
                    full_vdm_size = 277
                    physical_actuator_extent = 277
                }
            }
            {
                type = ndarray
                name = vdm-feedback-to-controller
                label = vdm-feedback-to-controller-f32
                config = { controller_command_extent = 221 vdm_size = 221 }
            }
        ]
        links = [
            { output = "pixel-calibration:calibrated" input = "shack-hartmann:row-block" }
            { output = "shack-hartmann:measurements" input = "reconstruction:measurements" }
            { output = "shack-hartmann:columns" input = "reconstruction:columns" }
            { output = "shack-hartmann:count" input = "reconstruction:count" }
            { output = "reconstruction:reconstructed" input = "closed-loop-correction:residual-error" }
            { output = "closed-loop-correction:correction" input = "controller-to-vdm:controller-command" }
            { output = "controller-to-vdm:vdm-command" input = "vdm-to-pdm:vdm-command" }
            { output = "vdm-to-pdm:requested-pdm-command" input = "pdm-command:requested" }
            { output = "pdm-command:constraint-feedback" input = "pdm-feedback-to-vdm:pdm-constraint-feedback" }
            { output = "pdm-feedback-to-vdm:vdm-constraint-feedback" input = "vdm-feedback-to-controller:vdm-constraint-feedback" }
        ]
        inputs = [
            "pixel-calibration:raw"
            "closed-loop-correction:constraint-feedback"
            "pixel-calibration:background"
            "shack-hartmann:subaperture-origins"
            "shack-hartmann:coordinates"
            "shack-hartmann:reference-slopes"
            "shack-hartmann:thresholds"
            "shack-hartmann:active"
            "reconstruction:reconstructor"
            "closed-loop-correction:shape-to-hidden"
            "closed-loop-correction:hidden-to-shape"
            "controller-to-vdm:controller-to-vdm"
            "vdm-to-pdm:active-to-full"
            "vdm-to-pdm:vdm-to-pdm"
            "pdm-feedback-to-vdm:full-to-active"
            "pdm-feedback-to-vdm:pdm-to-vdm"
            "vdm-feedback-to-controller:vdm-to-controller"
        ]
        outputs = [
            "pdm-command:demanded"
            "vdm-feedback-to-controller:controller-constraint-feedback"
        ]
    }
}
